    addBlock: "function kpisPage(){\n if(state.liveOnly && state.liveData){\n  const rows=(()=>{\n   const co=liveCompanyRecord();\n   const fk=co?.financialKpis;\n   if(!fk)return [];\n   if(Array.isArray(fk.kpis))return fk.kpis;\n   if(Array.isArray(fk.metrics))return fk.metrics;\n   if(fk.kpiValues && typeof fk.kpiValues==='object'){\n    const periods=Object.entries(fk.kpiValues);\n    if(!periods.length)return [];\n    const [period,values]=periods[periods.length-1];\n    return Object.entries(values||{}).filter(([k])=>k!=='manualEntries').map(([name,value])=>({\n     name,value,period,unit:'number',target:null,status:'Submitted',category:'Financial',frequency:'Period',owner:'Company'\n    }));\n   }\n   return [];\n  })();\n  if(!rows.length){\n   return `<section class=\"page\">${pageHead('KPI Centre','Track investor-agreed metrics, definitions, evidence and performance against plan.',`${btn('Submit period KPIs','submit-kpi','primary','upload')}${btn('Refresh','refresh-live','','refresh')}`)}${liveEmptyCard('No KPI values are on file yet. Submit period KPIs to populate this centre.')}</section>`;\n  }\n  return `<section class=\"page\">${pageHead('KPI Centre','Live KPI values from your portfolio company record.',`${btn('Submit period KPIs','submit-kpi','primary','upload')}${btn('Refresh','refresh-live','','refresh')}`)}\n <div class=\"grid g3 clean-kpi-grid\">${rows.map((k,i)=>{const current=typeof k.value==='number'?fmt.num(k.value):escapeHTML(String(k.value??'—'));return `<button class=\"card kpi-card clean-kpi\" data-action=\"kpi-detail\" data-index=\"${i}\"><div class=\"kpi-card-top\"><div><h3>${escapeHTML(String(k.name||'KPI'))}</h3><div class=\"tiny muted\">${escapeHTML(String(k.category||'Financial'))} · ${escapeHTML(String(k.frequency||k.period||'Period'))}</div></div>${pill(String(k.status||'Submitted'))}</div><div class=\"kpi-value-row\"><div class=\"big mono\">${current}</div></div><div class=\"kpi-owner-line\"><span>${escapeHTML(String(k.owner||'Company'))}</span><span>Live record</span></div></button>`}).join('')}</div></section>`;\n }\n return `<section class=\"page\">${pageHead('KPI Centre','Track investor-agreed metrics, definitions, evidence and performance against plan.',`${btn('Submit period KPIs','submit-kpi','primary','upload')}${btn('Export scorecard','export','','download')}`)}",
