    find: "function reportsPage(){const tabs=[['schedule','Reporting schedule'],['draft','Draft workspace'],['history','Submission history'],['templates','Templates']];return `<section class=\"page\">${pageHead('Reporting Centre','Prepare, validate, submit and track every report required by your investors.',`${btn('Submit report','submit-report','primary','upload')}${btn('Download template','download-template','','download')}`)}\n <div class=\"card\"><div class=\"card-head\"><div><h2>Portfolio reporting</h2><p>Reporting calendar and submission workspace</p></div><div class=\"actions\">${pill('2 active','warning')}<span class=\"tiny muted\">Next deadline: 12 Aug</span></div></div><div class=\"card-body\"><div class=\"tabs\">${tabs.map(([id,l])=>`<button class=\"tab ${state.reportTab===id?'active':''}\" data-action=\"report-tab\" data-tab=\"${id}\">${l}</button>`).join('')}</div><div id=\"reportTabBody\">${reportTabBody()}</div></div></div></section>`}",
    addBlock: "function reportsPage(){\n const liveBadge=state.liveOnly&&state.liveData?pill(`${liveReportingRequests().length||liveFinancialReports().length} records`,'info'):pill('2 active','warning');\n const tabs=[['schedule','Reporting schedule'],['draft','Draft workspace'],['history','Submission history'],['templates','Templates']];return `<section class=\"page\">${pageHead('Reporting Centre','Prepare, validate, submit and track every report required by your investors.',`${btn('Submit report','submit-report','primary','upload')}${btn('Download template','download-template','','download')}`)}\n <div class=\"card\"><div class=\"card-head\"><div><h2>Portfolio reporting</h2><p>Reporting calendar and submission workspace</p></div><div class=\"actions\">${liveBadge}<span class=\"tiny muted\">${state.liveOnly&&state.liveData?'Live totals':'Next deadline: 12 Aug'}</span></div></div><div class=\"card-body\"><div class=\"tabs\">${tabs.map(([id,l])=>`<button class=\"tab ${state.reportTab===id?'active':''}\" data-action=\"report-tab\" data-tab=\"${id}\">${l}</button>`).join('')}</div><div id=\"reportTabBody\">${reportTabBody()}</div></div></div></section>`\n}",
