    note: "reportTabBody live schedule/history tables sourced from liveReportingRequests()/liveFinancialReports()",
    find: " if(state.reportTab==='templates')return `<div class=\"folder-grid\">${[['Quarterly investor report','DOCX + XLSX','Standard reporting pack'],['Monthly management accounts','XLSX','Trial balance and operating schedules'],['ESG & impact questionnaire','XLSX','Annual data collection template'],['Board pack','PPTX','Board-ready governance template']].map(([n,t,d])=>`<div class=\"folder\" data-action=\"download-template\"><span class=\"folder-icon\">${icon('download')}</span><strong>${n}</strong><span>${d}</span><span class=\"status neutral\" style=\"margin-top:10px\">${t}</span></div>`).join('')}</div>`;",
    addBlock: " if(state.reportTab==='templates')return `<div class=\"folder-grid\">${[['Quarterly investor report','DOCX + XLSX','Standard reporting pack','INCOME_STATEMENT'],['Monthly management accounts','XLSX','Trial balance and operating schedules','INCOME_STATEMENT'],['ESG & impact questionnaire','XLSX','Annual data collection template','OPERATIONAL_KPIS'],['Balance sheet template','XLSX','Statement of financial position','BALANCE_SHEET'],['Cash flow template','XLSX','Cash movement schedule','CASHFLOW_STATEMENT']].map(([n,t,d,type])=>`<div class=\"folder\" data-action=\"download-template\" data-template=\"${type}\" data-name=\"${escapeHTML(n)}\"><span class=\"folder-icon\">${icon('download')}</span><strong>${n}</strong><span>${d}</span><span class=\"status neutral\" style=\"margin-top:10px\">${t}</span></div>`).join('')}</div>`;\n if(state.liveOnly && state.liveData && (state.reportTab==='schedule' || state.reportTab==='history')){\n  const reqs=liveReportingRequests();\n  const fin=liveFinancialReports();\n  const list=state.reportTab==='history'?fin:reqs;\n  if(state.reportTab==='history'){\n   return `<div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Report</th><th>Period</th><th>Type</th><th>Status</th></tr></thead><tbody>${(list.length?list:[{title:'No submissions yet',periodStart:'—',reportType:'—',status:'—'}]).map(r=>`<tr><td><div class=\"row-main\">${escapeHTML(String(r.title||'Report'))}</div><div class=\"row-sub\">${escapeHTML(String(r.id||''))}</div></td><td>${escapeHTML(String(r.reportingPeriod||r.periodStart||'—').slice(0,10))}</td><td>${escapeHTML(String(r.reportType||'—'))}</td><td>${pill(String(r.status||'—'))}</td></tr>`).join('')}</tbody></table></div>`;\n  }\n  return `<div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Reporting period</th><th>Due date</th><th>Status</th><th></th></tr></thead><tbody>${(list.length?list:[{reportingPeriod:'No requests yet',dueDate:'—',status:'—'}]).map(r=>`<tr><td><div class=\"row-main\">${escapeHTML(String(r.reportingPeriod||r.id||'Request'))}</div></td><td>${escapeHTML(String(r.dueDate||'—').slice(0,10))}</td><td>${pill(String(r.portalStatus||r.status||'Open'))}</td><td><button class=\"row-action\" data-action=\"submit-report\">${icon('upload')}</button></td></tr>`).join('')}</tbody></table></div>`;\n }",
