    addBlock: "function forecastsPage(){\n if(state.liveOnly && state.liveData){\n  return `<section class=\"page\">${pageHead('Actuals & Forecast Model','Submit actuals and maintain editable forecasts for upcoming months.',`${btn('Refresh','refresh-live','','refresh')}`)}${liveEmptyCard('A live actuals & forecast model has not been set up yet — the forecasting API is still pending. See design-refs/investee-portal-v8-backend-asks.md.')}</section>`;\n }\n const s=scenarios[state.scenario],current=forecastCurrentPeriod();return `<section class=\"page forecast-page\">${pageHead('Actuals & Forecast Model',`Submit ${current.label} actuals while maintaining editable forecasts for upcoming months. Closed periods lock automatically.`,`${btn('Submit actuals & forecast','submit-forecast','primary','send')}`)}",
