    label: "12-termsPage",
    isInsertion: false,
    note: "termsPage live branch — renders the real term sheet record, sign/download actions",
    find: "function termsPage(){return `<section class=\"page\">${pageHead('Term Sheet & Investment Terms','A plain-language, permission-controlled view of your executed investment terms.',`${btn('Download executed copy','download-term','primary','download')}${btn('Request clarification','term-question','','message')}`)}",
    addBlock: "function liveEmptyCard(message) {\n  return `<div class=\"empty\">${icon('info')}<strong>No data</strong><span>${escapeHTML(String(message || 'Nothing returned from the API yet.'))}</span></div>`;\n}\nfunction asLiveArray(v) {\n  if (Array.isArray(v)) return v;\n  if (v && Array.isArray(v.data)) return v.data;\n  if (v?.data?.termSheets && Array.isArray(v.data.termSheets)) return v.data.termSheets;\n  return [];\n}\nfunction liveTermSheets() {\n  return asLiveArray(state.livePayload?.termSheets?.data?.termSheets || state.livePayload?.termSheets);\n}\nfunction liveCompanyRecord() {\n  return state.livePayload?.company?.data || state.livePayload?.company || null;\n}\nfunction liveProfileRecord() {\n  return state.livePayload?.profile?.data || state.livePayload?.profile || null;\n}\nfunction liveDashboardRecord() {\n  return state.livePayload?.dashboard?.data || state.livePayload?.dashboard || null;\n}\nfunction liveReportingRequests() {\n  return asLiveArray(state.livePayload?.reportingRequests?.data || state.livePayload?.reportingRequests);\n}\nfunction liveFinancialReports() {\n  const raw = state.livePayload?.financialReports;\n  if (!raw) return [];\n  if (Array.isArray(raw)) return raw;\n  if (Array.isArray(raw.data)) return raw.data;\n  if (Array.isArray(raw.data?.reports)) return raw.data.reports;\n  if (Array.isArray(raw.data?.items)) return raw.data.items;\n  return [];\n}\nfunction liveSignatureRequests() {\n  if (!(state.liveOnly && state.liveData)) return signatureRequests;\n  const sheets = liveTermSheets();\n  if (!sheets.length) return [];\n  return sheets.map((ts) => {\n    const signed = Boolean(ts.isSigned || ts.applicantSignedAt || /signed|executed/i.test(String(ts.status || '')));\n    return {\n      id: String(ts.id),\n      document: String(ts.title || ts.documentFileName || 'Term sheet'),\n      category: 'Term sheet',\n      requestedBy: ts.createdBy ? `${ts.createdBy.firstName || ''} ${ts.createdBy.lastName || ''}`.trim() || 'Investor' : 'Investor',\n      recipients: 'Company authorised signatory',\n      status: signed ? 'Completed' : 'Awaiting your signature',\n      progress: signed ? 100 : 40,\n      due: String(ts.updatedAt || ts.createdAt || '').slice(0, 10) || '2026-09-30',\n      lastActivity: signed ? `Signed ${String(ts.applicantSignedAt || ts.signedAt || '').slice(0, 10)}` : 'Awaiting founder signature',\n      termSheetId: String(ts.id),\n      // BE sign route is /term-sheets/:applicationId/sign\n      applicationId: String(ts.applicationId || ts.application?.id || ''),\n    };\n  });\n}\nfunction emitIntegrationEvent(name, detail = {}, cancelable = false) {\n  return window.dispatchEvent(new CustomEvent(name, { detail, cancelable }));\n}\nfunction termsPage(){\n  if (state.liveOnly && state.liveData) {\n    const sheets = liveTermSheets();\n    const ts = sheets[0];\n    if (!ts) {\n      return `<section class=\"page\">${pageHead('Term Sheet & Investment Terms','Review the investment terms prepared for your application.',`${btn('Refresh','refresh-live','','refresh')}`)}${liveEmptyCard('No term sheet has been created for your application yet. Your investor will notify you when terms are ready.')}</section>`;\n    }\n    const biz = ts.application?.businessName || liveCompanyRecord()?.name || 'Your company';\n    const amount = ts.investmentAmount != null ? fmt.money(Number(ts.investmentAmount)) : '—';\n    const equity = ts.equityPercentage != null ? `${Number(ts.equityPercentage)}%` : '—';\n    const valuation = ts.valuation != null ? fmt.money(Number(ts.valuation)) : '—';\n    const status = String(ts.status || 'DRAFT');\n    const signed = Boolean(ts.isSigned || ts.applicantSignedAt || /signed|executed/i.test(status));\n    const actions = `${ts.documentUrl ? btn('Download document','download-term','','download') : ''}${!signed ? btn('Sign term sheet','sign-document','primary','edit',`data-id=\"${escapeHTML(String(ts.id))}\" data-term-sheet-id=\"${escapeHTML(String(ts.id))}\"`) : ''}${btn('Refresh','refresh-live','','refresh')}`;\n    return `<section class=\"page\">${pageHead('Term Sheet & Investment Terms','Live term sheet from your application record.',actions)}\n <div class=\"term-hero\"><div class=\"term-hero-head\"><div><div class=\"eyebrow\" style=\"color:#b8b0ff\">${escapeHTML(String(ts.title || 'Term sheet'))}</div><h2>${escapeHTML(String(biz))}</h2><p>Status ${escapeHTML(status)} · Updated ${escapeHTML(String(ts.updatedAt || ts.createdAt || '').slice(0, 10))}</p></div>${pill(status.replace(/_/g, ' '), signed ? 'success' : 'warning')}</div><div class=\"term-grid\"><div class=\"term-stat\"><span>Investment</span><strong>${amount}</strong></div><div class=\"term-stat\"><span>Equity</span><strong>${equity}</strong></div><div class=\"term-stat\"><span>Pre-money value</span><strong>${valuation}</strong></div><div class=\"term-stat\"><span>Stage</span><strong>${escapeHTML(String(ts.application?.currentStage || '—'))}</strong></div></div></div>\n <div class=\"card\" style=\"margin-top:14px\"><div class=\"card-head\"><div><h2>Key terms</h2><p>From the term sheet record</p></div></div><div class=\"card-body\"><dl class=\"detail-list\"><div class=\"detail-row\"><dt>Title</dt><dd>${escapeHTML(String(ts.title || '—'))}</dd></div><div class=\"detail-row\"><dt>Key terms</dt><dd>${escapeHTML(String(ts.keyTerms || '—'))}</dd></div><div class=\"detail-row\"><dt>Conditions</dt><dd>${escapeHTML(String(ts.conditions || '—'))}</dd></div><div class=\"detail-row\"><dt>Timeline</dt><dd>${escapeHTML(String(ts.timeline || '—'))}</dd></div></dl></div></div></section>`;\n  }\n  return `<section class=\"page\">${pageHead('Term Sheet & Investment Terms','A plain-language, permission-controlled view of your executed investment terms.',`${btn('Download executed copy','download-term','primary','download')}${btn('Request clarification','term-question','','message')}`)}",
