function applyStep(src, step) {
  const { label, isInsertion, find, addBlock } = step
  if (addBlock && src.includes(addBlock)) {
    console.log("skip (already applied)", label)
    return src
  }
  if (!src.includes(find)) {
    console.warn("MISS", label, "— anchor/find text not found; runtime may have changed upstream")
    return src
  }
  // IMPORTANT: use a replacer FUNCTION, not a replacement string. This
  // codebase uses "$$(" (querySelectorAll helper) throughout its hand-patched
  // blocks, and String.prototype.replace treats a STRING replacement's "$$"
  // (and "$&", "$`", "$'", "$<digit>") as special substitution patterns even
  // when the search value is a plain string — silently collapsing "$$(" to
  // "$(" in the output. A function replacer's return value is inserted
  // literally, sidestepping that whole class of bug (caught in this session:
  // a first pass silently turned every "$$('.nav-item',...)" into
  // "$('.nav-item',...)", a real function with different behaviour).
  if (isInsertion) {
    // Insert addBlock immediately before the anchor line `find`.
    return src.replace(find, () => addBlock + "\n" + find)
  }
  // Replace: `find` (raw/vendor text) → `addBlock` (hand-patched text).
  return src.replace(find, () => addBlock)
}

